let homeland=PalaisHome.normalize(localRead('homeland',null),Date.now()),homeGame=null,homeDraft=null,homeDressTab='face',homePanelType='';
const homeLooks=['玫瑰杏眼 · 栗色卷发','薄荷绿眸 · 蜂蜜短卷','紫藤蓝眸 · 编发盘髻','琥珀星眸 · 珍珠盘发'];
function homeAvatar(a=homeland.avatar,outfit=a.outfit){const ids=['rose','mint','lilac','gold'],body=Math.max(0,ids.indexOf(outfit)),head=a.look??0;return `<span class="paper-doll shape-${a.shape||'slim'} tint-${a.tint||'natural'}" role="img" aria-label="${escapeHtml(homeLooks[head])}，${escapeHtml(PalaisHome.clothes[outfit].name)}"><i class="doll-layer doll-body" style="background-position:${body/3*100}% 0"></i><i class="doll-layer doll-head" style="background-position:${head/3*100}% 0"></i>${a.blush!=='none'?`<i class="doll-blush ${a.blush==='peach'?'peach':''}"></i>`:''}${a.detail==='freckles'?'<i class="doll-freckles">· ·</i>':a.detail==='star'?'<i class="doll-star">✧</i>':''}</span>`}
function homeOwner(){return roles.find(r=>r.id===homeland.partner)}
function homeRelationshipPrompt(id){if(homeland.partner!==id)return '';return '\n你和用户共同拥有玫瑰家园'+(homeland.pet?'，共同领养了宠物'+homeland.pet.name:'')+'。最近的家园公开经历：'+homeland.log.slice(0,6).map(x=>x.text).join('；')+'。这些是你与用户在虚拟家园的共同经历，不能编造未发生的照料。'}
function homeStore(){try{if(homeGame){homeland.location={...homeGame.player};homeland.petMotion={...homeGame.pet}}localSave('homeland',homeland);return true}catch{toast('家园保存失败，请检查浏览器存储空间');return false}}
function stopHomeGame(){const g=homeGame;if(!g)return;homeStore();cancelAnimationFrame(g.frame);clearInterval(g.saveTimer);g.abort.abort();g.resize.disconnect();homeGame=null}
function homeDo(action){try{if(homeGame){homeland.location={...homeGame.player};homeland.petMotion={...homeGame.pet}}if(['adopt','partner'].includes(action.type)&&!roles.some(r=>r.id===(action.partner||action.id)))throw Error('请选择一位已有角色');const r=PalaisHome.apply(homeland,action);localSave('homeland',r.state);homeland=r.state;toast(r.message);renderHomeland();return true}catch(e){toast(e.message||'保存失败');return false}}
function renderHomeland(){
 if(tab!=='homeland')return;stopHomeGame();homeland=PalaisHome.normalize(homeland,Date.now());const loc=PalaisHomeWorld.safeLocation(homeland.location),pet=PalaisHomeWorld.safeLocation(homeland.petMotion),owner=homeOwner();
 screen.innerHTML=`<section class="home-game" aria-label="玫瑰家园游戏"><div class="game-viewport" id="gameViewport" tabindex="0" aria-label="家园地图，点击地面移动，也可用方向键或下方方向按钮"><div class="game-world" id="gameWorld"></div></div><header class="game-hud"><button class="game-round" id="leaveHome" aria-label="返回手机桌面">‹</button><button class="game-owner" id="homeOwnership"><span>ROSE COTTAGE</span><b>${owner?'你与'+escapeHtml(owner.name)+'的家':'玫瑰家园'}</b><small id="roomLabel">花园 · 点击地面散步</small></button><button class="game-points" id="gameTasks" aria-label="查看积分任务">✧ ${homeland.points}<small>家园积分</small></button></header><div class="game-side"><button id="gameDress">♙<small>装扮</small></button><button id="gamePet">♧<small>宠物</small></button><button id="gameMap">⌘<small>地图</small></button></div><button class="mini-map" id="miniMap" aria-label="打开地图"><span class="mini-house"></span><i id="miniDot"></i><small>花园地图</small></button><div class="game-bottom"><div class="direction-pad" aria-label="移动方向"><button data-dir="up" aria-label="向上跑">↑</button><button data-dir="left" aria-label="向左跑">←</button><span>跑</span><button data-dir="right" aria-label="向右跑">→</button><button data-dir="down" aria-label="向下跑">↓</button></div><div class="game-shortcuts"><button id="callPet">♡<small>招呼宠物</small></button><button id="nearAction">⌂<small id="nearLabel">进屋</small></button></div></div><div class="game-hint" id="gameHint">点击地面移动 · 按住方向键奔跑</div></section>`;
 const g=homeGame={player:loc,pet,petPath:[],petGoal:null,petRoomChange:false,path:[],arrival:null,dir:null,keys:new Set(),frame:0,last:0,nextPet:0,nextPetDoor:performance.now()+12000,abort:new AbortController(),camera:{x:0,y:0},width:0,height:0,room:null};
 const signal=g.abort.signal;g.resize=new ResizeObserver(()=>{const r=$('#gameViewport')?.getBoundingClientRect();if(r){g.width=r.width;g.height=r.height;homePosition(g)}});g.resize.observe($('#gameViewport'));
 $('#leaveHome').onclick=()=>{homePanelType='';current=null;go('home')};$('#homeOwnership').onclick=()=>openHomePanel('owners');$('#gameDress').onclick=()=>openHomePanel('dress');$('#gameTasks').onclick=()=>openHomePanel('tasks');$('#gamePet').onclick=()=>openHomePanel('pet');$('#gameMap').onclick=$('#miniMap').onclick=()=>openHomePanel('map');$('#callPet').onclick=homeCallPet;$('#nearAction').onclick=homeNear;
 $('#gameViewport').addEventListener('pointerup',e=>{if(e.target.closest('button'))return;const r=e.currentTarget.getBoundingClientRect();homeWalkTo({x:e.clientX-r.left+g.camera.x,y:e.clientY-r.top+g.camera.y})},{signal});
 document.querySelectorAll('[data-dir]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);g.dir=b.dataset.dir;g.path=[];g.arrival=null},{signal});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>g.dir=null,{signal});b.onclick=e=>{if(e.detail===0){const vec={up:[0,-60],down:[0,60],left:[-60,0],right:[60,0]}[b.dataset.dir];homeWalkTo({x:g.player.x+vec[0],y:g.player.y+vec[1]})}}});
 document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].includes(e.key)){e.preventDefault();g.keys.add(e.key);g.path=[];g.arrival=null}if(e.key===' '){e.preventDefault();homeNear()}},{signal});document.addEventListener('keyup',e=>g.keys.delete(e.key),{signal});window.addEventListener('blur',()=>{g.keys.clear();g.dir=null},{signal});document.addEventListener('visibilitychange',()=>{g.keys.clear();g.dir=null;if(document.hidden)homeStore()},{signal});
 homeRenderRoom(g);g.saveTimer=setInterval(()=>{if(tab==='homeland'){homeStore();homeRefreshPlots()}},10000);g.frame=requestAnimationFrame(homeTick);
}
function homeRenderRoom(g){const room=g.player.room,m=PalaisHomeWorld.maps[room],world=$('#gameWorld');g.room=room;world.style.width=m.width+'px';world.style.height=m.height+'px';world.innerHTML=homeMapArt(room)+`<button class="world-hotspot door-hotspot" id="worldDoor" style="left:${m.door.x}px;top:${m.door.y}px" aria-label="${room==='garden'?'进入房屋':'走出房屋'}"><span>${room==='garden'?'⌂ 进屋':'↗ 去花园'}</span></button>${room==='garden'?`<div class="world-plots" id="worldPlots"></div><button class="world-hotspot neighbor-hotspot" id="worldNeighbors" style="left:165px;top:520px">拜访菜园</button>`:`<div class="room-ownership">${escapeHtml(profile.name)} ${homeOwner()?'♡ '+escapeHtml(homeOwner().name):'的玫瑰小屋'}<small>我们的家 · 宠物也可以进来玩</small></div><button class="world-hotspot indoor-pet" id="petBed" style="left:145px;top:490px">宠物小窝</button>`}<div class="world-player" id="homeActor">${homeAvatar()}<small>${escapeHtml(profile.name)}</small></div><button class="world-pet" id="movingPet" aria-label="走近宠物">${homeland.pet?homePetArt(homeland.pet.kind):''}<small>${escapeHtml(homeland.pet?.name||'')}</small></button>`;
 $('#worldDoor').onclick=()=>homeWalkTo(m.door,()=>homeChangeRoom());if($('#worldNeighbors'))$('#worldNeighbors').onclick=()=>homeWalkTo({x:165,y:550},()=>openHomePanel('neighbors'));if($('#petBed'))$('#petBed').onclick=()=>homeWalkTo({x:165,y:510},()=>openHomePanel('pet'));$('#movingPet').onclick=()=>homeWalkTo({x:g.pet.x,y:g.pet.y+30},()=>openHomePanel('pet'));$('#roomLabel').textContent=room==='garden'?'屋外花园 · 四季小菜园':'屋内客厅 · 我们共同的家';$('#miniMap small').textContent=room==='garden'?'花园地图':'室内地图';$('#miniMap').classList.toggle('inside',room==='inside');homeRefreshPlots();homePosition(g);
}
function homeRefreshPlots(){const wrap=$('#worldPlots');if(!wrap)return;wrap.innerHTML=homeland.plots.map((p,i)=>`<button class="world-plot" data-world-plot="${i}" aria-label="菜地 ${i+1}"><span>${p?(PalaisHome.ready(p,Date.now())?PalaisHome.crops[p.crop].fruit:p.watered?'🌿':'🌱'):'＋'}</span><small>${p?(PalaisHome.ready(p,Date.now())?'收获':p.watered?'生长中':'浇水'):'播种'}</small></button>`).join('');document.querySelectorAll('[data-world-plot]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.worldPlot);homeWalkTo({x:795+i%2*112,y:650+Math.floor(i/2)*115},()=>homePlot(i))})}
function homeWalkTo(p,arrival=null){const g=homeGame;if(!g)return;g.dir=null;g.keys.clear();g.path=PalaisHomeWorld.path(g.player.room,g.player,p);g.arrival=arrival;if(!g.path.length&&arrival&&Math.hypot(g.player.x-p.x,g.player.y-p.y)<50){g.arrival=null;arrival()}}
function homeChangeRoom(){const g=homeGame;if(!g)return;g.player={room:g.player.room==='garden'?'inside':'garden',x:0,y:0};Object.assign(g.player,PalaisHomeWorld.maps[g.player.room].spawn);g.path=[];g.arrival=null;homeStore();homeRenderRoom(g);$('#gameHint').textContent=g.player.room==='inside'?'欢迎回家 · 点门口可以回到花园':'花园很大，向右走就是小菜园'}
function homeNear(){const g=homeGame;if(!g)return;const door=PalaisHomeWorld.maps[g.player.room].door;if(g.player.room==='inside'||g.player.y<530&&g.player.x>340&&g.player.x<710){homeWalkTo(door,homeChangeRoom)}else if(g.player.room==='garden'&&g.player.x>720){const i=(g.player.y>730?2:0)+(g.player.x>890?1:0);homePlot(i)}else if(homeland.pet&&g.player.room===g.pet.room&&Math.hypot(g.player.x-g.pet.x,g.player.y-g.pet.y)<150){openHomePanel('pet')}else homeWalkTo(door,homeChangeRoom)}
function homeCallPet(){const g=homeGame;if(!homeland.pet){openHomePanel('pet');return}g.petGoal='follow';g.petPath=PalaisHomeWorld.path(g.pet.room,g.pet,g.pet.room===g.player.room?{x:g.player.x-40,y:g.player.y}:PalaisHomeWorld.maps[g.pet.room].door);$('#gameHint').textContent=homeland.pet.name+'听到你的呼唤，正在过来';g.nextPetDoor=performance.now()+20000}
function homeFollowPath(entity,path,speed,dt){if(!path.length)return false;const target=path[0],dx=target.x-entity.x,dy=target.y-entity.y,dist=Math.hypot(dx,dy),amount=speed*dt;if(dist<=amount){entity.x=target.x;entity.y=target.y;path.shift()}else{entity.x+=dx/dist*amount;entity.y+=dy/dist*amount}return true}
function homeTick(t){const g=homeGame;if(!g||tab!=='homeland')return;const dt=Math.min(.05,(t-(g.last||t))/1000);g.last=t;const paused=document.hidden||!!document.querySelector('dialog[open]');let moving=false;
 if(!paused){const dx=(g.dir==='right'||g.keys.has('ArrowRight')||g.keys.has('d')?1:0)-(g.dir==='left'||g.keys.has('ArrowLeft')||g.keys.has('a')?1:0),dy=(g.dir==='down'||g.keys.has('ArrowDown')||g.keys.has('s')?1:0)-(g.dir==='up'||g.keys.has('ArrowUp')||g.keys.has('w')?1:0);if(dx||dy){const length=Math.hypot(dx,dy),p=PalaisHomeWorld.move(g.player.room,g.player,dx/length*230*dt,dy/length*230*dt);moving=p.x!==g.player.x||p.y!==g.player.y;Object.assign(g.player,p)}else moving=homeFollowPath(g.player,g.path,205,dt);
  if(!g.path.length&&g.arrival){const fn=g.arrival;g.arrival=null;fn();if(homeGame!==g)return}
  if(homeland.pet){if(!g.petPath.length){if(g.petGoal==='door'||g.petGoal==='follow'&&g.pet.room!==g.player.room){g.pet.room=g.pet.room==='garden'?'inside':'garden';Object.assign(g.pet,PalaisHomeWorld.maps[g.pet.room].spawn);g.petPath=PalaisHomeWorld.path(g.pet.room,g.pet,g.petGoal==='follow'?{x:g.player.x-35,y:g.player.y}:g.pet);g.petGoal=g.petGoal==='follow'?'follow':null;g.nextPet=t+2000;g.nextPetDoor=t+22000}else if(g.petGoal==='follow'){g.petGoal=null;g.nextPet=t+6000}else if(t>g.nextPetDoor){g.petGoal='door';g.petPath=PalaisHomeWorld.path(g.pet.room,g.pet,PalaisHomeWorld.maps[g.pet.room].door)}else if(t>g.nextPet){const m=PalaisHomeWorld.maps[g.pet.room],p={x:60+Math.random()*(m.width-120),y:300+Math.random()*(m.height-370)};g.petPath=PalaisHomeWorld.path(g.pet.room,g.pet,p);g.nextPet=t+6000}}
   homeFollowPath(g.pet,g.petPath,100,dt);
  }
 }const actor=$('#homeActor');actor?.classList.toggle('walking',moving);$('#movingPet')?.classList.toggle('walking',!!g.petPath.length&&!paused);homePosition(g);g.frame=requestAnimationFrame(homeTick);
}
function homePosition(g){if(!$('#gameWorld'))return;const c=PalaisHomeWorld.camera(g.player.room,g.player,g.width||376,g.height||750);g.camera=c;$('#gameWorld').style.transform=`translate(${-c.x}px,${-c.y}px)`;const actor=$('#homeActor');if(actor){actor.style.left=g.player.x+'px';actor.style.top=g.player.y+'px';actor.style.zIndex=Math.round(g.player.y)}const pet=$('#movingPet');if(pet){pet.hidden=!homeland.pet||g.pet.room!==g.player.room;pet.style.left=g.pet.x+'px';pet.style.top=g.pet.y+'px';pet.style.zIndex=Math.round(g.pet.y)}const m=PalaisHomeWorld.maps[g.player.room];$('#miniDot').style.left=g.player.x/m.width*100+'%';$('#miniDot').style.top=g.player.y/m.height*100+'%';$('#nearLabel').textContent=g.player.room==='inside'?'出门':g.player.x>720?'照顾菜地':'进屋'}
function homePanel(html){const d=$('#utilityDialog');d.classList.add('home-dialog');d.innerHTML=`<button class="home-close" aria-label="关闭家园面板">×</button>${html}`;if(!d.open)d.showModal();d.querySelector('.home-close').onclick=()=>{d.close();homePanelType=''};d.onclose=()=>{d.classList.remove('home-dialog');homeDraft=null;homePanelType=''};return d}
function openHomePanel(type){homePanelType=type;if(type==='dress'){homeDraft={...homeland.avatar};homeDressTab='face';renderHomeDress();return}if(type==='pet'){renderHomePet();return}if(type==='tasks'){renderHomeTasks();return}if(type==='owners'){renderHomeOwners();return}if(type==='neighbors'){const d=homePanel(`<div class="eyebrow">NEIGHBOURS</div><h2>去朋友家摘菜</h2><p class="section-note">本地虚拟菜园 · 每日最多三位，每位一次</p>${roles.map(r=>`<button class="plot-row" data-neighbor="${escapeHtml(r.id)}"><b>${escapeHtml(r.emoji)}</b><div>${escapeHtml(r.name)}的菜园<small>${homeland.daily.stolen.includes(r.id)?'今天已经摘过':'采摘一篮成熟蔬菜 · +8 积分'}</small></div></button>`).join('')||'<p>先在微信里创建角色吧。</p>'}`);d.querySelectorAll('[data-neighbor]').forEach(b=>b.onclick=()=>{homeDo({type:'steal',id:b.dataset.neighbor});openHomePanel('neighbors')});return}if(type==='map')renderHomeMap()}
function renderHomeOwners(){const owner=homeOwner(),d=homePanel(`<div class="eyebrow">OUR HOME</div><h2>我们共同的家</h2><div class="ownership-card">${escapeHtml(profile.name)}<span>♡</span>${owner?escapeHtml(owner.name):'等待一位共同主人'}<small>${homeland.pet?'共同领养：'+escapeHtml(homeland.pet.name):'这里也为未来的小宠物留了一个窝'}</small></div><form id="ownerForm"><label>和哪位角色一起生活？<select name="partner" required><option value="">选择共同主人</option>${roles.map(r=>`<option value="${escapeHtml(r.id)}" ${r.id===homeland.partner?'selected':''}>${escapeHtml(r.name)}</option>`).join('')}</select></label><button class="primary full">保存共同主人</button></form><p class="section-note">房屋和宠物使用同一位共同主人。<br>共同经历可供这位角色后续聊天时回忆。</p>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();if(homeDo({type:'partner',id:e.target.partner.value}))renderHomeOwners()}}
function homePlot(i){const p=homeland.plots[i];if(p){if(PalaisHome.ready(p,Date.now())){homeDo({type:'harvest',index:i});return}if(!p.watered){homeDo({type:'water',index:i});return}toast('正在生长，还需 '+Math.ceil(Math.max(0,PalaisHome.crops[p.crop].time-Date.now()+p.planted)/1000)+' 秒');return}const d=homePanel(`<div class="eyebrow">PLANT SOMETHING LOVELY</div><h2>${i+1} 号菜地 · 选种子</h2>${Object.entries(PalaisHome.crops).map(([id,c])=>`<button class="plot-row" data-seed="${id}"><b>${c.fruit}</b><div>${c.name}<small>${c.time/60000} 分钟成熟 · 花费 ${c.cost} 积分 · 收获 +${c.reward}</small></div></button>`).join('')}`);d.querySelectorAll('[data-seed]').forEach(b=>b.onclick=()=>{if(homeDo({type:'plant',index:i,crop:b.dataset.seed}))d.close()})}
function renderHomePet(){const p=homeland.pet;if(!p){const d=homePanel(`<div class="eyebrow">A LITTLE FAMILY</div><h2>一起领养小伙伴</h2><form id="adoptPet"><div class="adopt-options">${[['cat','奶糖猫'],['bunny','云朵兔'],['dog','布丁犬']].map(([k,n])=>`<label><input type="radio" name="kind" value="${k}" ${k==='cat'?'checked':''}><span>${homePetArt(k)}<b>${n}</b></span></label>`).join('')}</div><label>给 TA 起名字<input name="petName" required maxlength="12" value="奶糖"></label><label>和哪位智能体一起领养？<select name="partner" required><option value="">请选择一起领养的角色</option>${roles.map(r=>`<option value="${escapeHtml(r.id)}" ${r.id===homeland.partner?'selected':''}>${escapeHtml(r.name)}</option>`).join('')}</select></label><p class="section-note">选好后，房子和宠物都会属于你们两位。<br>${roles.length?'免费领养，照料后会慢慢成长。':'请先去微信创建一位角色。'}</p><button class="primary full" ${roles.length?'':'disabled'}>一起接 TA 回家</button></form>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();if(homeDo({type:'adopt',kind:e.target.kind.value,name:e.target.petName.value,partner:e.target.partner.value}))renderHomePet()};return}
 const n=PalaisHome.needs(p,Date.now()),owner=homeOwner(),petRoom=homeGame?.pet.room||homeland.petMotion.room,d=homePanel(`<div class="eyebrow">OUR LITTLE COMPANION</div><h2>${escapeHtml(p.name)}</h2><div class="pet-portrait">${homePetArt(p.kind)}</div><p class="pet-owners">${escapeHtml(profile.name)} ${owner?'♡ '+escapeHtml(owner.name):''}共同的小伙伴</p><p class="section-note">${petRoom==='inside'?'正在客厅里玩耍':'正在花园散步'} · ${p.xp>=100?'已长大':'幼年'} · 成长 ${p.xp}</p>${[['food','饱腹'],['clean','清洁'],['joy','心情']].map(([k,l])=>`<div class="pet-meter">${l}<progress max="100" value="${n[k]}"></progress><small>${n[k]}</small></div>`).join('')}<div class="care-actions">${[['food','喂食'],['clean','洗澡'],['joy','玩耍']].map(([k,l])=>`<button class="secondary" data-care="${k}">${l}</button>`).join('')}</div><button class="primary full" id="partnerCare" ${owner?'':'disabled'}>请${owner?escapeHtml(owner.name):'伙伴'}一起照料</button><p class="section-note">同种照料间隔一分钟；伙伴互动为本地玩法。<br>宠物会自己散步，也会进屋或回到花园。</p><button class="text-button full" id="editHomeOwners">查看房屋与宠物的共同主人</button><h3>我们的小日记</h3>${homeland.log.slice(0,5).map(l=>`<p class="home-log">${escapeHtml(l.text)}</p>`).join('')}`);
 d.querySelectorAll('[data-care]').forEach(b=>b.onclick=()=>{homeDo({type:'care',kind:b.dataset.care});renderHomePet()});$('#partnerCare').onclick=()=>{if(!owner)return;const lowest=Object.keys(n).sort((a,b)=>n[a]-n[b])[0];homeDo({type:'care',kind:lowest,actor:owner.name});renderHomePet()};$('#editHomeOwners').onclick=renderHomeOwners;
}
function renderHomeDress(){const a=homeDraft||{...homeland.avatar};homeDraft=a;const choice=(key,items)=>`<div class="dress-options">${items.map(([v,n])=>`<button type="button" data-choice="${key}" data-value="${v}" aria-pressed="${a[key]===v}" class="${a[key]===v?'chosen':''}">${n}</button>`).join('')}</div>`;
 const d=homePanel(`<div class="eyebrow">THE PAPER DOLL ATELIER</div><h2>我的纸娃娃</h2><div class="dress-stage"><div id="liveDoll">${homeAvatar(a)}</div><span>实时试穿 · 选择即预览</span></div><div class="dress-tabbar"><button data-dress-tab="face" class="${homeDressTab==='face'?'chosen':''}">面容与发型</button><button data-dress-tab="clothes" class="${homeDressTab==='clothes'?'chosen':''}">衣橱与商店</button></div><div class="dress-controls">${homeDressTab==='face'?`<h3>选择面容与发型</h3><div class="face-presets">${homeLooks.map((n,i)=>`<button data-choice="look" data-value="${i}" aria-pressed="${a.look===i}" class="${a.look===i?'chosen':''}"><span class="face-thumb">${homeAvatar({...a,look:i})}</span><small>${n.split(' · ').join('<br>')}</small></button>`).join('')}</div><h3>发色色调</h3>${choice('tint',[['natural','原本色调'],['cocoa','深可可'],['honey','暖蜂蜜']])}<h3>脸颊</h3>${choice('blush',[['none','清透'],['soft','玫瑰腮红'],['peach','蜜桃腮红']])}<h3>脸部小细节</h3>${choice('detail',[['none','素净'],['freckles','小雀斑'],['star','眼下星星']])}<h3>身形</h3>${choice('shape',[['slim','纤细'],['natural','自然'],['tall','修长']])}<p class="section-note">面容预设包含对应眼型、眼色与发型；<br>色调、腮红、脸饰和身形可继续搭配。</p>`:`<p class="section-note">点击衣服看上身效果，确认后才会扣积分。</p><div class="clothes-grid">${Object.entries(PalaisHome.clothes).map(([id,c])=>`<button data-choice="outfit" data-value="${id}" aria-pressed="${a.outfit===id}" class="outfit ${a.outfit===id?'chosen':''}"><span class="outfit-preview">${homeAvatar(a,id)}</span><b>${c.name}</b><small>${homeland.owned.includes(id)?'已拥有':c.price+' 积分'}</small></button>`).join('')}</div>`}</div><div class="dress-confirm"><small id="dressPrice"></small><button class="primary full" id="saveHomeLook">保存装扮</button></div>`);
 const refresh=()=>{const v=homeDraft;$('#liveDoll').innerHTML=homeAvatar(v);const owned=homeland.owned.includes(v.outfit),price=PalaisHome.clothes[v.outfit].price;$('#dressPrice').textContent=owned?'装扮已拥有 · 当前 '+homeland.points+' 积分':'试穿中 · 购买需 '+price+' 积分 · 当前 '+homeland.points+' 积分';$('#saveHomeLook').textContent=owned?'保存这套装扮':'购买并保存 · '+price+' 积分';d.querySelectorAll('[data-choice]').forEach(b=>{const value=b.dataset.choice==='look'?Number(b.dataset.value):b.dataset.value,yes=v[b.dataset.choice]===value;b.classList.toggle('chosen',yes);b.setAttribute('aria-pressed',String(yes))})};
 d.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{homeDraft[b.dataset.choice]=b.dataset.choice==='look'?Number(b.dataset.value):b.dataset.value;refresh()});d.querySelectorAll('[data-dress-tab]').forEach(b=>b.onclick=()=>{homeDressTab=b.dataset.dressTab;renderHomeDress()});$('#saveHomeLook').onclick=()=>{if(homeDo({type:'customize',avatar:{...homeDraft},buy:!homeland.owned.includes(homeDraft.outfit)}))d.close()};refresh();
}
function renderHomeTasks(){const daily=PalaisHome.normalize(homeland,Date.now()).daily,d=homePanel(`<div class="eyebrow">LITTLE DAILY JOYS</div><h2>今日家园任务</h2><p class="section-note">✧ ${homeland.points} 家园积分 · 每天重新开始</p>${[['visit','来家园看看',true,10],['care','照料宠物两次',daily.care>=2,20],['water','给两块菜地浇水',daily.water>=2,15],['harvest','收获一块菜地',daily.harvest>=1,20]].map(([id,n,done,reward])=>`<div class="task-row"><div>${n}<small>奖励 ${reward} 积分</small></div><button class="secondary" data-task="${id}" ${!done||daily.claimed.includes(id)?'disabled':''}>${daily.claimed.includes(id)?'已领取':done?'领取':'进行中'}</button></div>`).join('')}`);d.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{homeDo({type:'claim',id:b.dataset.task});renderHomeTasks()})}
function renderHomeMap(){const g=homeGame,room=g.player.room,m=PalaisHomeWorld.maps[room],d=homePanel(`<div class="eyebrow">EXPLORE OUR LITTLE WORLD</div><h2>${room==='garden'?'花园全景':'小屋平面图'}</h2><div class="map-overview" id="mapOverview" style="aspect-ratio:${m.width}/${m.height}">${homeMapArt(room)}<i style="left:${g.player.x/m.width*100}%;top:${g.player.y/m.height*100}%"></i></div><p class="section-note">粉点是你的位置 · 点击地图可以走过去</p><div class="map-destinations"><button class="secondary" id="mapDoor">${room==='garden'?'回小屋':'去花园'}</button>${room==='garden'?'<button class="secondary" id="mapFarm">去菜园</button><button class="secondary" id="mapNeighbors">朋友菜园</button>':'<button class="secondary" id="mapPetBed">去宠物小窝</button>'}</div>`);$('#mapOverview').onclick=e=>{const r=e.currentTarget.getBoundingClientRect(),p={x:(e.clientX-r.left)/r.width*m.width,y:(e.clientY-r.top)/r.height*m.height};d.close();homeWalkTo(p)};$('#mapDoor').onclick=()=>{d.close();homeWalkTo(m.door,homeChangeRoom)};if($('#mapFarm'))$('#mapFarm').onclick=()=>{d.close();homeWalkTo({x:850,y:660})};if($('#mapNeighbors'))$('#mapNeighbors').onclick=()=>{d.close();homeWalkTo({x:165,y:550},()=>openHomePanel('neighbors'))};if($('#mapPetBed'))$('#mapPetBed').onclick=()=>{d.close();homeWalkTo({x:165,y:510})}}
